private byte [] getUnDecodedImageBytes(COSStream st) throws IOException { 
ByteArrayOutputStream baos = new ByteArrayOutputStream(); 
IOUtil.writeStream(st.getUnfilteredStream(), baos); 
return baos.toByteArray(); 
